"use strict";
// The CommonJS JSON-module idiom real packages ship (statuses' codes.json,
// mime-db's db.json): a relative .json document required as a VALUE and
// read through the binding — a sibling, a nested subdirectory, and the
// same document required again from another file of the package (Node
// answers the second require from its module cache).
const meta = require("./meta.json");
const table = require("./data/table.json");
const twin = require("./inner/twin.js");

exports.summary = function summary() {
  return meta.label + "@" + meta.release + " x" + table.entries.length;
};
exports.flag = function flag() {
  return meta.stable ? "stable:" + meta.weight : "beta:" + meta.weight;
};
/** @param {number} i */
exports.describe = function describe(i) {
  const entry = table.entries[i];
  return meta.label + ":" + entry.name + "=" + entry.code;
};
exports.twinTag = function twinTag() {
  return twin.tag();
};
